import { MeshStandardNodeMaterial, LineBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group, Mesh, Shape, ExtrudeGeometry, EdgesGeometry,
    LineSegments, PointLight, Color, DoubleSide
  } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  const group = new Group();
  group.name = 'hub-pricing-badge';

  const accent = new Color(colors.accent);
  const paper = new Color(colors.paper);
  const ink = new Color(colors.ink);
  const surface = new Color(colors.surface);

  // --- Capsule-shaped body (rounded-rect extrude, PBR machined metal) ---
  const w = 0.92, h = 0.34, r = h / 2, depth = 0.05;
  const shape = new Shape();
  shape.absarc(-w / 2 + r, 0, r, Math.PI / 2, -Math.PI / 2, true);
  shape.lineTo(w / 2 - r, -r);
  shape.absarc(w / 2 - r, 0, r, -Math.PI / 2, Math.PI / 2, true);
  shape.lineTo(-w / 2 + r, r);

  const bodyGeo = new ExtrudeGeometry(shape, {
    depth, bevelEnabled: true, bevelThickness: 0.012, bevelSize: 0.012,
    bevelSegments: 3, steps: 1, curveSegments: 24
  });
  bodyGeo.center();

  const bodyMat = new MeshStandardNodeMaterial({
    color: paper,
    metalness: 0.5,
    roughness: 0.52,
    envMapIntensity: 0.6,
    side: DoubleSide
  });

  // ceramic grain map (async, cached)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.anisotropy = 4;
      bodyMat.map = tex;
      bodyMat.roughnessMap = tex;
      bodyMat.needsUpdate = true;
    });
  }

  const body = new Mesh(bodyGeo, bodyMat);
  body.castShadow = false;
  group.add(body);

  // --- Accent edge light: bright edges + small back rim light ---
  const edges = new EdgesGeometry(bodyGeo, 30);
  const edgeMat = new LineBasicNodeMaterial({ color: accent, transparent: true, opacity: 0.95 });
  const edgeLines = new LineSegments(edges, edgeMat);
  group.add(edgeLines);

  const rim = new PointLight(accent, 0.7, 1.6, 2.0);
  rim.position.set(0.35, 0.08, -0.25);
  group.add(rim);

  // Ambient/rest supports metal — key fill from scene applies; add a soft local fill
  const fill = new PointLight(paper, 0.35, 2.2, 2.0);
  fill.position.set(-0.3, 0.1, 0.4);
  group.add(fill);

  // --- Subtle idle breathing so it isn't frozen (<=2%) ---
  const breath = gsap.to(group.scale, {
    x: 1.015, y: 1.015, z: 1.015,
    duration: 2.6, ease: 'sine.inOut', yoyo: true, repeat: -1
  });

  // --- Interactions ---
  const state = { hovering: false };
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group.position, { y: '+=0.15', duration: 0.55, ease: 'power3.out' }, 0);
  hoverTl.to(edgeMat, { opacity: 1, duration: 0.35, ease: 'power2.out' }, 0);
  hoverTl.to(rim, { intensity: 1.15, duration: 0.35, ease: 'power2.out' }, 0);

  const clickTl = gsap.timeline({ paused: true });
  clickTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' }, 0);
  clickTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' });

  group.userData.handlers = {
    pointerover: () => { state.hovering = true; hoverTl.play(); },
    pointerout:  () => { state.hovering = false; hoverTl.reverse(); },
    pointerdown: () => {
      clickTl.play(0);
      rim.intensity = 1.5;
      gsap.to(rim, { intensity: 0.7, duration: 0.6, ease: 'power2.out' });
      ctx.emit('hub-pricing.select', { source: group.name });
    }
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    breath.kill(); hoverTl.kill(); clickTl.kill();
    gsap.killTweensOf(group.position); gsap.killTweensOf(group.scale); gsap.killTweensOf(rim);
    bodyGeo.dispose(); edges.dispose();
    bodyMat.dispose();
    if (bodyMat.map) bodyMat.map.dispose();
    edgeMat.dispose();
    group.remove(body, edgeLines, rim, fill);
  };

  return group;
}
